-- Table for e-signatures for our Power BI Report
CREATE OR REPLACE TABLE PAYROLL_DB.RPT.SIGNATURES (
	APPROVER_EMAIL VARCHAR(16777216) NOT NULL COMMENT 'Email of the approver.',
	IMAGE_BASE64 VARCHAR(16777216) COMMENT 'E-Signature image in Base64'
);

